using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Sigov.Application.Empresarial;
namespace Sigov.Api.Controllers;
[ApiController,Authorize,Route("api/empresarial/comercial")] public sealed class EmpresarialComercialController:ControllerBase { private readonly IEmpresarialService _service; public EmpresarialComercialController(IEmpresarialComercialService service)=>_service=service;
