[HttpGet("relatorios/exportar-csv")] public async Task<IActionResult> Csv(CancellationToken ct){var r=await _service.ListarAsync("emp_comercial_cliente",1,100,ct);var csv="id;codigo;status;titulo\n"+string.Join("\n",r.Value?.Items.Select(x=>$"{x.Id};{x.Codigo};{x.Status};{x.Titulo}")??Array.Empty<string>());return File(System.Text.Encoding.UTF8.GetBytes(csv),"text/csv","comercial.csv");}
